var c={name:"artisan",description:"Laravel Artisan Command",generateSpec:async(p,o)=>{var{stdout:a}=await o({command:"php",args:["artisan","list","--format=json"]});let i=[];try{JSON.parse(a).commands.filter(t=>t.name!=="_complete").map(t=>{i.push({name:t.name,description:t.description,icon:"spec://localhost/icons/remote/f4e92a7ad8d2625b.png",args:Object.keys(t.definition.arguments).map(e=>{let n=t.definition.arguments[e];return{name:n.name,description:n.description,isOptional:!n.is_required}}),options:Object.keys(t.definition.options).map(e=>{let n=t.definition.options[e],s=[n.name];return n.shortcut!==""&&s.push(n.shortcut),{name:s,description:n.description}})})})}catch{}return{name:"artisan",debounce:!0,subcommands:i}}},m=c;export{m as default};
